import time, random
from heapq import heappush, heappop
random.seed(5)
N=4096; E=16384
edges=[]
for i in range(N-1): edges.append((i,i+1,1,'step%05d'%i,-1))
for i in range(E-(N-1)):
    edges.append((random.randrange(N),random.randrange(N),1+random.randrange(1000),'c%06d'%i,-1 if i%8 else i%1024))
out4=[[] for _ in range(N)]; out3=[[] for _ in range(N)]; cmds=[[] for _ in range(N)]
for (u,v,c,cmd,g) in edges:
    out4[u].append((v,c,cmd,g)); out3[u].append((v,c,g)); cmds[u].append(cmd)
masks=[bytes([1 if random.random()<0.5 else 0 for _ in range(1024)]) for _ in range(32)]
INF=float('inf')

def search4(mask):
    dist=[INF]*N; dist[0]=0; heap=[(0,0)]
    while heap:
        cost,state=heappop(heap)
        if cost!=dist[state]: continue
        for (target,weight,_command,guard) in out4[state]:
            if guard>=0 and not mask[guard]: continue
            following=cost+weight
            if following<dist[target]:
                dist[target]=following; heappush(heap,(following,target))
    return dist

def search3(mask):
    dist=[INF]*N; dist[0]=0; heap=[(0,0)]; push=heappush; pop=heappop
    while heap:
        cost,state=pop(heap)
        if cost!=dist[state]: continue
        for (target,weight,guard) in out3[state]:
            if guard>=0 and not mask[guard]: continue
            following=cost+weight
            if following<dist[target]:
                dist[target]=following; push(heap,(following,target))
    return dist

def search3e(mask):
    # skip guard check when no guards at all in this adjacency
    dist=[INF]*N; dist[0]=0; heap=[(0,0)]; push=heappush; pop=heappop
    while heap:
        cost,state=pop(heap)
        if cost is not dist[state] if False else cost!=dist[state]: continue
        for edge in out3[state]:
            target,weight,guard=edge
            if guard>=0:
                if not mask[guard]: continue
            following=cost+weight
            if following<dist[target]:
                dist[target]=following; push(heap,(following,target))
    return dist

for name,fn in [('4-tuple',search4),('3-tuple',search3),('3-tuple-b',search3e)]:
    t=time.time()
    for m in masks: fn(m)
    print(name, '%.2f ms'%((time.time()-t)/len(masks)*1000))
